            }
            for (j = 1; j <= (2 * i - 1); j++) {
                if (j == 1 || j == (2 * i - 1))//Logic for printing star
                    System.out.print("*");
                else
                    System.out.print(" ");//if logic fails print space
            }
            System.out.println("");
        }

        //Lower Inverted V pattern
        for (i = 2; i <= n; i++) {
            for (j = i; j < n; j++) {
                System.out.print(" ");//Print spaces
            }
            for (j = 1; j <= (2 * i - 1); j++) {
                if (j == 1 || j == (2 * i - 1))//Logic for printing star
                    System.out.print("*");
                else
                    System.out.print(" ");//if logic fails print space
            }
            System.out.println("");
        }
    }
}
